use std::{
    collections::HashMap,
    panic::{RefUnwindSafe, UnwindSafe},
    sync::Arc,
};

use {
    grep_matcher::{ByteSet, LineTerminator, Match, Matcher, NoError},
    regex_automata::{
        meta::Regex, util::captures::Captures, util::pool::Pool, Input,
        PatternID,
    },
    regex_syntax::{
        ast::{self, Ast},
        hir::{
            self,
            literal::{Literal, Seq},
            Hir, HirKind, Look,
        },
        utf8::Utf8Sequences,
    },
};

use crate::{
    ast::AstAnalysis,
    config::{Config, ConfiguredHIR},
    error::{Error, ErrorKind},
    matcher::RegexCaptures,
    strip::strip_from_match,
};

type PoolFn =
    Box<dyn Fn() -> Captures + Send + Sync + UnwindSafe + RefUnwindSafe>;

/// A matcher for implementing "word match" semantics.
///
/// This type also owns the configuration, HIR assembly, literal extraction,
/// line-terminator stripping and AST analysis needed to build a matcher.
#[derive(Debug)]
pub(crate) struct WordMatcher {
    /// The regex which is roughly `(?:^|\W)(<original pattern>)(?:$|\W)`.
    regex: Regex,
    /// The HIR that produced the regex above. We don't keep the HIR for the
    /// `original` regex.
    ///
    /// We put this in an `Arc` because by the time it gets here, it won't
    /// change. And because cloning and dropping an `Hir` is somewhat expensive
    /// due to its deep recursive representation.
    chir: Arc<ConfiguredHIR>,
    /// The original regex supplied by the user, which we use in a fast path
    /// to try and detect matches before deferring to slower engines.
    original: Regex,
    /// A map from capture group name to capture group index.
    names: HashMap<String, usize>,
    /// A thread-safe pool of reusable buffers for finding the match offset of
    /// the inner group.
    caps: Arc<Pool<Captures, PoolFn>>,
    /// Matcher construction options originally kept on the builder.
    config: Config,
    /// Literal extraction class expansion limit.
    extract_limit_class: usize,
    /// Literal extraction bounded-repeat unrolling limit.
    extract_limit_repeat: usize,
    /// Literal extraction per-literal length limit.
    extract_limit_literal_len: usize,
    /// Literal extraction total sequence size limit.
    extract_limit_total: usize,
    /// Whether AST inspection has seen an uppercase literal.
    any_uppercase: bool,
    /// Whether AST inspection has seen any literal at all.
    any_literal: bool,
    /// When true, matches are trimmed to word boundaries.
    word_mode: bool,
}

impl Clone for WordMatcher {
    fn clone(&self) -> WordMatcher {
        // We implement Clone manually so that we get a fresh Pool such that it
        // can set its own thread owner. This permits each thread usings `caps`
        // to hit the fast path.
        //
        // Note that cloning a regex is "cheap" since it uses reference
        // counting internally.
        let re = self.regex.clone();
        WordMatcher {
            regex: self.regex.clone(),
            chir: Arc::clone(&self.chir),
            original: self.original.clone(),
            names: self.names.clone(),
            caps: Arc::new(Pool::new(Box::new(move || re.create_captures()))),
            config: self.config.clone(),
            extract_limit_class: self.extract_limit_class,
            extract_limit_repeat: self.extract_limit_repeat,
            extract_limit_literal_len: self.extract_limit_literal_len,
            extract_limit_total: self.extract_limit_total,
            any_uppercase: self.any_uppercase,
            any_literal: self.any_literal,
            word_mode: self.word_mode,
        }
    }
}

impl WordMatcher {
    /// Create a new matcher from the given pattern that only produces matches
    /// that are considered "words."
    ///
    /// The given options are used to construct the regular expression
    /// internally.
    pub(crate) fn new(chir: ConfiguredHIR) -> Result<WordMatcher, Error> {
        let config = chir.config().clone();
        let original = chir.clone().into_anchored().to_regex()?;
        let chir = Arc::new(chir.into_word()?);
        let regex = chir.to_regex()?;
        let caps = Arc::new(Pool::new({
            let regex = regex.clone();
            Box::new(move || regex.create_captures()) as PoolFn
        }));

        let mut names = HashMap::new();
        let it = regex.group_info().pattern_names(PatternID::ZERO);
        for (i, optional_name) in it.enumerate() {
            if let Some(name) = optional_name {
                names.insert(name.to_string(), i.checked_sub(1).unwrap());
            }
        }
        Ok(WordMatcher {
            regex,
            chir,
            original,
            names,
            caps,
            config,
            extract_limit_class: 10,
            extract_limit_repeat: 10,
            extract_limit_literal_len: 100,
            extract_limit_total: 64,
            any_uppercase: false,
            any_literal: false,
            word_mode: true,
        })
    }

    /// Create a matcher that does not impose word boundaries.
    pub(crate) fn new_standard(
        chir: ConfiguredHIR,
    ) -> Result<WordMatcher, Error> {
        let config = chir.config().clone();
        let chir = Arc::new(chir);
        let regex = chir.to_regex()?;
        let original = regex.clone();
        let caps = Arc::new(Pool::new({
            let regex = regex.clone();
            Box::new(move || regex.create_captures()) as PoolFn
        }));
        Ok(WordMatcher {
            regex,
            chir,
            original,
            names: HashMap::new(),
            caps,
            config,
            extract_limit_class: 10,
            extract_limit_repeat: 10,
            extract_limit_literal_len: 100,
            extract_limit_total: 64,
            any_uppercase: false,
            any_literal: false,
            word_mode: false,
        })
    }

    /// Create a helper used while assembling configuration and analyzing
    /// patterns.
    pub(crate) fn analyzer() -> WordMatcher {
        let regex = placeholder_regex();
        let original = regex.clone();
        let caps = Arc::new(Pool::new({
            let regex = regex.clone();
            Box::new(move || regex.create_captures()) as PoolFn
        }));
        WordMatcher {
            regex,
            chir: placeholder_chir(),
            original,
            names: HashMap::new(),
            caps,
            config: Config::default(),
            extract_limit_class: 10,
            extract_limit_repeat: 10,
            extract_limit_literal_len: 100,
            extract_limit_total: 64,
            any_uppercase: false,
            any_literal: false,
            word_mode: false,
        }
    }

    /// Return the underlying regex used to match at word boundaries.
    ///
    /// The original regex is in the capture group at index 1.
    pub(crate) fn regex(&self) -> &Regex {
        &self.regex
    }

    /// Return the underlying HIR for the regex used to match at word
    /// boundaries.
    pub(crate) fn chir(&self) -> &ConfiguredHIR {
        &self.chir
    }

    /// Return a clone of the configuration currently stored on this matcher.
    pub(crate) fn config(&self) -> Config {
        self.config.clone()
    }

    pub(crate) fn set_case_insensitive(&mut self, yes: bool) {
        self.config.case_insensitive = yes;
    }

    pub(crate) fn set_case_smart(&mut self, yes: bool) {
        self.config.case_smart = yes;
    }

    pub(crate) fn set_multi_line(&mut self, yes: bool) {
        self.config.multi_line = yes;
    }

    pub(crate) fn set_dot_matches_new_line(&mut self, yes: bool) {
        self.config.dot_matches_new_line = yes;
    }

    pub(crate) fn set_swap_greed(&mut self, yes: bool) {
        self.config.swap_greed = yes;
    }

    pub(crate) fn set_ignore_whitespace(&mut self, yes: bool) {
        self.config.ignore_whitespace = yes;
    }

    pub(crate) fn set_unicode(&mut self, yes: bool) {
        self.config.unicode = yes;
    }

    pub(crate) fn set_octal(&mut self, yes: bool) {
        self.config.octal = yes;
    }

    pub(crate) fn set_size_limit(&mut self, bytes: usize) {
        self.config.size_limit = bytes;
    }

    pub(crate) fn set_dfa_size_limit(&mut self, bytes: usize) {
        self.config.dfa_size_limit = bytes;
    }

    pub(crate) fn set_nest_limit(&mut self, limit: u32) {
        self.config.nest_limit = limit;
    }

    pub(crate) fn set_line_terminator(&mut self, line_term: Option<u8>) {
        self.config.line_terminator = line_term.map(LineTerminator::byte);
    }

    pub(crate) fn set_crlf(&mut self, yes: bool) {
        if yes {
            self.config.line_terminator = Some(LineTerminator::crlf());
        } else {
            self.config.line_terminator = None;
        }
        self.config.crlf = yes;
    }

    pub(crate) fn set_word(&mut self, yes: bool) {
        self.config.word = yes;
    }

    pub(crate) fn set_fixed_strings(&mut self, yes: bool) {
        self.config.fixed_strings = yes;
    }

    pub(crate) fn set_whole_line(&mut self, yes: bool) {
        self.config.whole_line = yes;
    }

    pub(crate) fn replace_config(&mut self, config: Config) {
        self.config = config;
    }

    fn config_is_case_insensitive(
        &self,
        any_literal: bool,
        any_uppercase: bool,
    ) -> bool {
        if self.config.case_insensitive {
            return true;
        }
        if !self.config.case_smart {
            return false;
        }
        any_literal && !any_uppercase
    }

    fn config_is_fixed_strings<P: AsRef<str>>(&self, patterns: &[P]) -> bool {
        if self.config.case_insensitive || self.config.case_smart {
            return false;
        }
        if self.config.fixed_strings {
            if let Some(lineterm) = self.config.line_terminator {
                for p in patterns.iter() {
                    if Self::literal_has_line_terminator(lineterm, p.as_ref())
                    {
                        return false;
                    }
                }
            }
            return true;
        }
        for p in patterns.iter() {
            let p = p.as_ref();
            if p.chars().any(regex_syntax::is_meta_character) {
                return false;
            }
            if let Some(lineterm) = self.config.line_terminator {
                if Self::literal_has_line_terminator(lineterm, p) {
                    return false;
                }
            }
        }
        true
    }

    fn literal_has_line_terminator(
        lineterm: LineTerminator,
        literal: &str,
    ) -> bool {
        if lineterm.is_crlf() {
            literal.as_bytes().iter().copied().any(|b| b == b'\r' || b == b'\n')
        } else {
            literal.as_bytes().iter().copied().any(|b| b == lineterm.as_byte())
        }
    }

    fn line_anchor_start(&self) -> hir::Look {
        if self.config.crlf {
            hir::Look::StartCRLF
        } else {
            hir::Look::StartLF
        }
    }

    fn line_anchor_end(&self) -> hir::Look {
        if self.config.crlf {
            hir::Look::EndCRLF
        } else {
            hir::Look::EndLF
        }
    }

    /// Assemble an HIR for the given patterns using this matcher's config.
    pub(crate) fn assemble_hir<P: AsRef<str>>(
        config: Config,
        patterns: &[P],
    ) -> Result<ConfiguredHIR, Error> {
        let mut worker = WordMatcher::analyzer();
        worker.replace_config(config);
        worker.assemble_from_patterns(patterns)
    }

    fn assemble_from_patterns<P: AsRef<str>>(
        &mut self,
        patterns: &[P],
    ) -> Result<ConfiguredHIR, Error> {
        let hir = if self.config_is_fixed_strings(patterns) {
            let mut alts = vec![];
            for p in patterns.iter() {
                alts.push(Hir::literal(p.as_ref().as_bytes()));
            }
            log::debug!(
                "assembling HIR from {} fixed string literals",
                alts.len()
            );
            Hir::alternation(alts)
        } else {
            let mut alts = vec![];
            for p in patterns.iter() {
                alts.push(if self.config.fixed_strings {
                    format!("(?:{})", regex_syntax::escape(p.as_ref()))
                } else {
                    format!("(?:{})", p.as_ref())
                });
            }
            let pattern = alts.join("|");
            let ast = ast::parse::ParserBuilder::new()
                .nest_limit(self.config.nest_limit)
                .octal(self.config.octal)
                .ignore_whitespace(self.config.ignore_whitespace)
                .build()
                .parse(&pattern)
                .map_err(Error::generic)?;
            let analysis = AstAnalysis::from_ast(&ast);
            self.any_literal = analysis.any_literal();
            self.any_uppercase = analysis.any_uppercase();
            let any_literal = self.any_literal;
            let any_uppercase = self.any_uppercase;
            let mut hir = hir::translate::TranslatorBuilder::new()
                .utf8(false)
                .case_insensitive(self.config_is_case_insensitive(
                    any_literal,
                    any_uppercase,
                ))
                .multi_line(self.config.multi_line)
                .dot_matches_new_line(self.config.dot_matches_new_line)
                .crlf(self.config.crlf)
                .swap_greed(self.config.swap_greed)
                .unicode(self.config.unicode)
                .build()
                .translate(&pattern, &ast)
                .map_err(Error::generic)?;
            hir = match self.config.line_terminator {
                None => hir,
                Some(line_term) => strip_from_match(hir, line_term)?,
            };
            hir
        };
        Ok(ConfiguredHIR::from_parts(self.config.clone(), hir))
    }

    /// Compile the given HIR into a regex using the HIR's own configuration.
    pub(crate) fn compile_regex(chir: &ConfiguredHIR) -> Result<Regex, Error> {
        let meta = Regex::config()
            .utf8_empty(false)
            .nfa_size_limit(Some(chir.config().size_limit))
            .onepass_size_limit(Some(10 * (1 << 20)))
            .dfa_size_limit(Some(1 * (1 << 20)))
            .dfa_state_limit(Some(1_000))
            .hybrid_cache_capacity(chir.config().dfa_size_limit);
        Regex::builder()
            .configure(meta)
            .build_from_hir(chir.hir())
            .map_err(Error::regex)
    }

    /// Wrap an HIR so that matches must occur at word boundaries.
    pub(crate) fn apply_word_boundaries(
        chir: ConfiguredHIR,
    ) -> Result<ConfiguredHIR, Error> {
        let mut worker = WordMatcher::analyzer();
        worker.replace_config(chir.config().clone());
        worker.wrap_word_hir(chir)
    }

    fn wrap_word_hir(
        &self,
        chir: ConfiguredHIR,
    ) -> Result<ConfiguredHIR, Error> {
        let (config, hir) = chir.into_parts();
        let non_word = {
            let mut nw_config = config.clone();
            nw_config.fixed_strings = false;
            ConfiguredHIR::from_config_and_patterns(nw_config, &[r"\W"])?
        };
        let line_anchor_start = Hir::look(self.line_anchor_start());
        let line_anchor_end = Hir::look(self.line_anchor_end());
        let wrapped = Hir::concat(vec![
            Hir::alternation(vec![
                line_anchor_start,
                non_word.hir().clone(),
            ]),
            Hir::capture(hir::Capture {
                index: 1,
                name: None,
                sub: Box::new(Self::renumber_capture_indices(hir)?),
            }),
            Hir::alternation(vec![non_word.hir().clone(), line_anchor_end]),
        ]);
        Ok(ConfiguredHIR::from_parts(config, wrapped))
    }

    /// Force the HIR to match a complete line.
    pub(crate) fn apply_whole_line(chir: ConfiguredHIR) -> ConfiguredHIR {
        let mut worker = WordMatcher::analyzer();
        worker.replace_config(chir.config().clone());
        worker.wrap_whole_line(chir)
    }

    fn wrap_whole_line(&self, chir: ConfiguredHIR) -> ConfiguredHIR {
        let (config, hir) = chir.into_parts();
        let wrapped = Hir::concat(vec![
            Hir::look(self.line_anchor_start()),
            hir,
            Hir::look(self.line_anchor_end()),
        ]);
        ConfiguredHIR::from_parts(config, wrapped)
    }

    /// Force the HIR to match the entire haystack.
    pub(crate) fn apply_anchored(chir: ConfiguredHIR) -> ConfiguredHIR {
        let (config, hir) = chir.into_parts();
        let wrapped = Hir::concat(vec![
            Hir::look(hir::Look::Start),
            hir,
            Hir::look(hir::Look::End),
        ]);
        ConfiguredHIR::from_parts(config, wrapped)
    }

    fn renumber_capture_indices(hir: Hir) -> Result<Hir, Error> {
        Ok(match hir.into_kind() {
            HirKind::Empty => Hir::empty(),
            HirKind::Literal(hir::Literal(lit)) => Hir::literal(lit),
            HirKind::Class(cls) => Hir::class(cls),
            HirKind::Look(x) => Hir::look(x),
            HirKind::Repetition(mut x) => {
                x.sub = Box::new(Self::renumber_capture_indices(*x.sub)?);
                Hir::repetition(x)
            }
            HirKind::Capture(mut cap) => {
                cap.index = match cap.index.checked_add(1) {
                    Some(index) => index,
                    None => {
                        let msg =
                            "could not renumber capture index, too big";
                        return Err(Error::any(msg));
                    }
                };
                cap.sub = Box::new(Self::renumber_capture_indices(*cap.sub)?);
                Hir::capture(cap)
            }
            HirKind::Concat(subs) => {
                let subs = subs
                    .into_iter()
                    .map(Self::renumber_capture_indices)
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::concat(subs)
            }
            HirKind::Alternation(subs) => {
                let subs = subs
                    .into_iter()
                    .map(Self::renumber_capture_indices)
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::alternation(subs)
            }
        })
    }

    /// Compile patterns into a ready-to-search matcher.
    pub(crate) fn compile<P: AsRef<str>>(
        &self,
        patterns: &[P],
    ) -> Result<WordMatcher, Error> {
        let mut chir = Self::assemble_hir(self.config.clone(), patterns)?;
        if chir.config().word && !chir.config().whole_line {
            let mut compiled = WordMatcher::new(chir)?;
            compiled.copy_extract_limits(self);
            Ok(compiled)
        } else {
            if chir.config().whole_line {
                chir = Self::apply_whole_line(chir);
            }
            let mut compiled = WordMatcher::new_standard(chir)?;
            compiled.copy_extract_limits(self);
            Ok(compiled)
        }
    }

    fn copy_extract_limits(&mut self, other: &WordMatcher) {
        self.extract_limit_class = other.extract_limit_class;
        self.extract_limit_repeat = other.extract_limit_repeat;
        self.extract_limit_literal_len = other.extract_limit_literal_len;
        self.extract_limit_total = other.extract_limit_total;
    }

    /// The line terminator that should be advertised to callers after HIR
    /// analysis.
    pub(crate) fn advertised_line_terminator(&self) -> Option<LineTerminator> {
        if self.chir.hir().properties().look_set().contains_anchor_haystack()
        {
            None
        } else {
            self.chir.config().line_terminator
        }
    }

    /// Compute the set of bytes that can never appear in a match.
    pub(crate) fn bytes_that_never_match(&self) -> ByteSet {
        self.chir.non_matching_bytes()
    }

    pub(crate) fn one_regex_from_seq(&self, seq: &Seq) -> Result<Option<Regex>, Error> {
        let Some(lits) = seq.literals() else { return Ok(None) };
        if lits.is_empty() {
            return Ok(None);
        }
        if !self.extract_limits_allow(lits.len()) {
            return Ok(None);
        }
        let mut alts = vec![];
        for lit in lits.iter() {
            alts.push(Hir::literal(lit.as_bytes()));
        }
        let hir = Hir::alternation(alts);
        log::debug!("extracted fast line regex: {:?}", hir.to_string());
        let re = Regex::builder()
            .configure(Regex::config().utf8_empty(false))
            .build_from_hir(&hir)
            .map_err(Error::regex)?;
        Ok(Some(re))
    }

    fn extract_limits_allow(&self, lit_count: usize) -> bool {
        if lit_count == 0 {
            return false;
        }
        if lit_count > self.extract_limit_total {
            return false;
        }
        true
    }

    /// Pick inner literals from an HIR/regex pair.
    pub(crate) fn pick_inner_literals(
        &self,
        chir: &ConfiguredHIR,
        re: &Regex,
    ) -> Seq {
        if chir.config().line_terminator.is_none() {
            log::trace!(
                "skipping inner literal extraction, \
                 no line terminator is set"
            );
            return Seq::infinite();
        }
        if re.is_accelerated() {
            log::trace!(
                "skipping inner literal extraction, \
                 existing regex is believed to already be accelerated",
            );
            return Seq::infinite();
        }
        if chir.hir().properties().is_alternation_literal() {
            log::trace!(
                "skipping inner literal extraction, \
                 found alternation of literals, deferring to regex engine",
            );
            return Seq::infinite();
        }
        self.extract_untagged(chir.hir())
    }

    pub(crate) fn extract_untagged(&self, hir: &Hir) -> Seq {
        let mut seq = self.extract(hir);
        log::trace!("extracted inner literals: {:?}", seq.seq);
        seq.seq.optimize_for_prefix_by_preference();
        log::trace!(
            "extracted inner literals after optimization: {:?}",
            seq.seq
        );
        if !self.seq_is_good(&seq) {
            log::trace!(
                "throwing away inner literals because they might be slow"
            );
            seq.make_infinite();
        }
        seq.seq
    }

    fn extract(&self, hir: &Hir) -> TSeq {
        use regex_syntax::hir::HirKind::*;

        match *hir.kind() {
            Empty | Look(_) => TSeq::singleton(hir::literal::Literal::exact(vec![])),
            Literal(hir::Literal(ref bytes)) => {
                let mut seq =
                    TSeq::singleton(hir::literal::Literal::exact(bytes.to_vec()));
                self.enforce_literal_len(&mut seq);
                seq
            }
            Class(hir::Class::Unicode(ref cls)) => {
                self.extract_class_unicode(cls)
            }
            Class(hir::Class::Bytes(ref cls)) => {
                self.extract_class_bytes(cls)
            }
            Repetition(ref rep) => self.extract_repetition(rep),
            Capture(hir::Capture { ref sub, .. }) => self.extract(sub),
            Concat(ref hirs) => self.extract_concat(hirs.iter()),
            Alternation(ref hirs) => self.extract_alternation(hirs.iter()),
        }
    }

    fn extract_concat<'a, I: Iterator<Item = &'a Hir>>(&self, it: I) -> TSeq {
        let mut seq = TSeq::singleton(hir::literal::Literal::exact(vec![]));
        let mut prev: Option<TSeq> = None;
        for hir in it {
            if seq.is_inexact() {
                if seq.is_empty() {
                    return seq;
                }
                if self.seq_is_really_good(&seq) {
                    return seq;
                }
                prev = Some(match prev {
                    None => seq,
                    Some(prev) => self.seq_choose(prev, seq),
                });
                seq = TSeq::singleton(hir::literal::Literal::exact(vec![]));
                seq.make_not_prefix();
            }
            seq = self.cross(seq, self.extract(hir));
        }
        if let Some(prev) = prev {
            self.seq_choose(prev, seq)
        } else {
            seq
        }
    }

    fn extract_alternation<'a, I: Iterator<Item = &'a Hir>>(
        &self,
        it: I,
    ) -> TSeq {
        let mut seq = TSeq::empty();
        for hir in it {
            if !seq.is_finite() {
                break;
            }
            seq = self.union(seq, &mut self.extract(hir));
        }
        seq
    }

    fn extract_repetition(&self, rep: &hir::Repetition) -> TSeq {
        let mut subseq = self.extract(&rep.sub);
        match *rep {
            hir::Repetition { min: 0, max, greedy, .. } => {
                if max != Some(1) {
                    subseq.make_inexact();
                }
                let mut empty = TSeq::singleton(hir::literal::Literal::exact(vec![]));
                if !greedy {
                    std::mem::swap(&mut subseq, &mut empty);
                }
                self.union(subseq, &mut empty)
            }
            hir::Repetition { min, max: Some(max), .. } if min == max => {
                assert!(min > 0);
                let limit =
                    u32::try_from(self.extract_limit_repeat).unwrap_or(u32::MAX);
                let mut seq = TSeq::singleton(hir::literal::Literal::exact(vec![]));
                for _ in 0..std::cmp::min(min, limit) {
                    if seq.is_inexact() {
                        break;
                    }
                    seq = self.cross(seq, subseq.clone());
                }
                if usize::try_from(min).is_err() || min > limit {
                    seq.make_inexact();
                }
                seq
            }
            hir::Repetition { min, max: Some(max), .. } if min < max => {
                assert!(min > 0);
                let limit =
                    u32::try_from(self.extract_limit_repeat).unwrap_or(u32::MAX);
                let mut seq = TSeq::singleton(hir::literal::Literal::exact(vec![]));
                for _ in 0..std::cmp::min(min, limit) {
                    if seq.is_inexact() {
                        break;
                    }
                    seq = self.cross(seq, subseq.clone());
                }
                seq.make_inexact();
                seq
            }
            hir::Repetition { .. } => {
                subseq.make_inexact();
                subseq
            }
        }
    }

    fn extract_class_unicode(&self, cls: &hir::ClassUnicode) -> TSeq {
        if self.class_over_limit_unicode(cls) {
            return TSeq::infinite();
        }
        let mut seq = TSeq::empty();
        for r in cls.iter() {
            for ch in r.start()..=r.end() {
                seq.push(hir::literal::Literal::from(ch));
            }
        }
        self.enforce_literal_len(&mut seq);
        seq
    }

    fn extract_class_bytes(&self, cls: &hir::ClassBytes) -> TSeq {
        if self.class_over_limit_bytes(cls) {
            return TSeq::infinite();
        }
        let mut seq = TSeq::empty();
        for r in cls.iter() {
            for b in r.start()..=r.end() {
                seq.push(hir::literal::Literal::from(b));
            }
        }
        self.enforce_literal_len(&mut seq);
        seq
    }

    fn class_over_limit_unicode(&self, cls: &hir::ClassUnicode) -> bool {
        let mut count = 0;
        for r in cls.iter() {
            if count > self.extract_limit_class {
                return true;
            }
            count += r.len();
        }
        count > self.extract_limit_class
    }

    fn class_over_limit_bytes(&self, cls: &hir::ClassBytes) -> bool {
        let mut count = 0;
        for r in cls.iter() {
            if count > self.extract_limit_class {
                return true;
            }
            count += r.len();
        }
        count > self.extract_limit_class
    }

    fn cross(&self, mut seq1: TSeq, mut seq2: TSeq) -> TSeq {
        if !seq2.prefix {
            return self.seq_choose(seq1, seq2);
        }
        if seq1
            .max_cross_len(&seq2)
            .map_or(false, |len| len > self.extract_limit_total)
        {
            seq2.make_infinite();
        }
        seq1.cross_forward(&mut seq2);
        assert!(seq1.len().map_or(true, |x| x <= self.extract_limit_total));
        self.enforce_literal_len(&mut seq1);
        seq1
    }

    fn union(&self, mut seq1: TSeq, seq2: &mut TSeq) -> TSeq {
        if seq1
            .max_union_len(seq2)
            .map_or(false, |len| len > self.extract_limit_total)
        {
            seq1.keep_first_bytes(4);
            seq2.keep_first_bytes(4);
            seq1.dedup();
            seq2.dedup();
            if seq1
                .max_union_len(seq2)
                .map_or(false, |len| len > self.extract_limit_total)
            {
                seq2.make_infinite();
            }
        }
        seq1.union(seq2);
        assert!(seq1.len().map_or(true, |x| x <= self.extract_limit_total));
        seq1
    }

    fn enforce_literal_len(&self, seq: &mut TSeq) {
        seq.keep_first_bytes(self.extract_limit_literal_len);
    }

    fn seq_is_good(&self, seq: &TSeq) -> bool {
        if self.seq_has_poisonous_literal(seq) {
            return false;
        }
        let Some(min) = seq.min_literal_len() else { return false };
        let Some(len) = seq.len() else { return false };
        if min <= 1 {
            return len <= 3;
        }
        min >= 2 && len <= 64 && len <= self.extract_limit_total
    }

    fn seq_is_really_good(&self, seq: &TSeq) -> bool {
        if self.seq_has_poisonous_literal(seq) {
            return false;
        }
        let Some(min) = seq.min_literal_len() else { return false };
        let Some(len) = seq.len() else { return false };
        min >= 3 && len <= 8 && len <= self.extract_limit_total
    }

    fn seq_has_poisonous_literal(&self, seq: &TSeq) -> bool {
        let Some(lits) = seq.literals() else { return false };
        if lits.len() > self.extract_limit_total {
            return true;
        }
        lits.iter().any(is_poisonous)
    }

    fn seq_choose(&self, seq1: TSeq, seq2: TSeq) -> TSeq {
        if !seq1.is_finite() {
            return seq2;
        } else if !seq2.is_finite() {
            return seq1;
        }
        if self.seq_has_poisonous_literal(&seq1) {
            return seq2;
        } else if self.seq_has_poisonous_literal(&seq2) {
            return seq1;
        }
        let Some(min1) = seq1.min_literal_len() else { return seq2 };
        let Some(min2) = seq2.min_literal_len() else { return seq1 };
        if min1 < min2 {
            return seq2;
        } else if min2 < min1 {
            return seq1;
        }
        let len1 = seq1.len().unwrap();
        let len2 = seq2.len().unwrap();
        if len1 < len2 {
            return seq2;
        } else if len2 < len1 {
            return seq1;
        }
        if len1 > self.extract_limit_total {
            return seq2;
        }
        seq1
    }

    fn reset_analysis(&mut self) {
        self.any_uppercase = false;
        self.any_literal = false;
    }

    pub(crate) fn analysis_any_uppercase(&self) -> bool {
        self.any_uppercase
    }

    pub(crate) fn analysis_any_literal(&self) -> bool {
        self.any_literal
    }

    pub(crate) fn inspect_ast(&mut self, ast: &Ast) {
        if self.analysis_done() {
            return;
        }
        match *ast {
            Ast::Empty(_) => {}
            Ast::Flags(_)
            | Ast::Dot(_)
            | Ast::Assertion(_)
            | Ast::Class(ast::Class::Unicode(_))
            | Ast::Class(ast::Class::Perl(_)) => {}
            Ast::Literal(ref x) => {
                self.inspect_ast_literal(x);
            }
            Ast::Class(ast::Class::Bracketed(ref x)) => {
                self.inspect_ast_class_set(&x.kind);
            }
            Ast::Repetition(ref x) => {
                self.inspect_ast(x.ast.as_ref());
            }
            Ast::Group(ref x) => {
                self.inspect_ast(x.ast.as_ref());
            }
            Ast::Alternation(ref alt) => {
                for x in &alt.asts {
                    self.inspect_ast(x);
                }
            }
            Ast::Concat(ref alt) => {
                for x in &alt.asts {
                    self.inspect_ast(x);
                }
            }
        }
    }

    fn inspect_ast_class_set(&mut self, ast: &ast::ClassSet) {
        if self.analysis_done() {
            return;
        }
        match *ast {
            ast::ClassSet::Item(ref item) => {
                self.inspect_ast_class_set_item(item);
            }
            ast::ClassSet::BinaryOp(ref x) => {
                self.inspect_ast_class_set(&x.lhs);
                self.inspect_ast_class_set(&x.rhs);
            }
        }
    }

    fn inspect_ast_class_set_item(&mut self, ast: &ast::ClassSetItem) {
        if self.analysis_done() {
            return;
        }
        match *ast {
            ast::ClassSetItem::Empty(_)
            | ast::ClassSetItem::Ascii(_)
            | ast::ClassSetItem::Unicode(_)
            | ast::ClassSetItem::Perl(_) => {}
            ast::ClassSetItem::Literal(ref x) => {
                self.inspect_ast_literal(x);
            }
            ast::ClassSetItem::Range(ref x) => {
                self.inspect_ast_literal(&x.start);
                self.inspect_ast_literal(&x.end);
            }
            ast::ClassSetItem::Bracketed(ref x) => {
                self.inspect_ast_class_set(&x.kind);
            }
            ast::ClassSetItem::Union(ref union) => {
                for x in &union.items {
                    self.inspect_ast_class_set_item(x);
                }
            }
        }
    }

    fn inspect_ast_literal(&mut self, ast: &ast::Literal) {
        self.any_literal = true;
        self.any_uppercase = self.any_uppercase || ast.c.is_uppercase();
    }

    fn analysis_done(&self) -> bool {
        self.any_uppercase && self.any_literal
    }

    pub(crate) fn remove_line_terminator(
        expr: Hir,
        line_term: LineTerminator,
    ) -> Result<Hir, Error> {
        if line_term.is_crlf() {
            let expr1 = Self::remove_line_terminator_ascii(expr, b'\r')?;
            Self::remove_line_terminator_ascii(expr1, b'\n')
        } else {
            Self::remove_line_terminator_ascii(expr, line_term.as_byte())
        }
    }

    fn remove_line_terminator_ascii(expr: Hir, byte: u8) -> Result<Hir, Error> {
        if !byte.is_ascii() {
            return Err(Error::new(ErrorKind::InvalidLineTerminator(byte)));
        }
        let ch = char::from(byte);
        let invalid = || Err(Error::new(ErrorKind::NotAllowed(ch.to_string())));
        Ok(match expr.into_kind() {
            HirKind::Empty => Hir::empty(),
            HirKind::Literal(hir::Literal(lit)) => {
                if lit.iter().find(|&&b| b == byte).is_some() {
                    return invalid();
                }
                Hir::literal(lit)
            }
            HirKind::Class(hir::Class::Unicode(mut cls)) => {
                if cls.ranges().is_empty() {
                    return Ok(Hir::class(hir::Class::Unicode(cls)));
                }
                let remove = hir::ClassUnicode::new(Some(
                    hir::ClassUnicodeRange::new(ch, ch),
                ));
                cls.difference(&remove);
                if cls.ranges().is_empty() {
                    return invalid();
                }
                Hir::class(hir::Class::Unicode(cls))
            }
            HirKind::Class(hir::Class::Bytes(mut cls)) => {
                if cls.ranges().is_empty() {
                    return Ok(Hir::class(hir::Class::Bytes(cls)));
                }
                let remove = hir::ClassBytes::new(Some(
                    hir::ClassBytesRange::new(byte, byte),
                ));
                cls.difference(&remove);
                if cls.ranges().is_empty() {
                    return invalid();
                }
                Hir::class(hir::Class::Bytes(cls))
            }
            HirKind::Look(x) => Hir::look(x),
            HirKind::Repetition(mut x) => {
                x.sub = Box::new(Self::remove_line_terminator_ascii(
                    *x.sub, byte,
                )?);
                Hir::repetition(x)
            }
            HirKind::Capture(mut x) => {
                x.sub = Box::new(Self::remove_line_terminator_ascii(
                    *x.sub, byte,
                )?);
                Hir::capture(x)
            }
            HirKind::Concat(xs) => {
                let xs = xs
                    .into_iter()
                    .map(|e| Self::remove_line_terminator_ascii(e, byte))
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::concat(xs)
            }
            HirKind::Alternation(xs) => {
                let xs = xs
                    .into_iter()
                    .map(|e| Self::remove_line_terminator_ascii(e, byte))
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::alternation(xs)
            }
        })
    }

    pub(crate) fn bytes_excluded_from_match(expr: &Hir) -> ByteSet {
        let mut set = ByteSet::full();
        Self::remove_matching_bytes(expr, &mut set);
        set
    }

    fn remove_matching_bytes(expr: &Hir, set: &mut ByteSet) {
        match *expr.kind() {
            HirKind::Empty
            | HirKind::Look(Look::WordAscii | Look::WordAsciiNegate)
            | HirKind::Look(Look::WordUnicode | Look::WordUnicodeNegate) => {}
            HirKind::Look(Look::Start | Look::End) => {
                set.remove(b'\n');
            }
            HirKind::Look(Look::StartLF | Look::EndLF) => {
                set.remove(b'\n');
            }
            HirKind::Look(Look::StartCRLF | Look::EndCRLF) => {
                set.remove(b'\r');
                set.remove(b'\n');
            }
            HirKind::Literal(hir::Literal(ref lit)) => {
                for &b in lit.iter() {
                    set.remove(b);
                }
            }
            HirKind::Class(hir::Class::Unicode(ref cls)) => {
                for range in cls.iter() {
                    for seq in Utf8Sequences::new(range.start(), range.end()) {
                        for byte_range in seq.as_slice() {
                            set.remove_all(byte_range.start, byte_range.end);
                        }
                    }
                }
            }
            HirKind::Class(hir::Class::Bytes(ref cls)) => {
                for range in cls.iter() {
                    set.remove_all(range.start(), range.end());
                }
            }
            HirKind::Repetition(ref x) => {
                Self::remove_matching_bytes(&x.sub, set);
            }
            HirKind::Capture(ref x) => {
                Self::remove_matching_bytes(&x.sub, set);
            }
            HirKind::Concat(ref xs) => {
                for x in xs {
                    Self::remove_matching_bytes(x, set);
                }
            }
            HirKind::Alternation(ref xs) => {
                for x in xs {
                    Self::remove_matching_bytes(x, set);
                }
            }
        }
    }

    /// Attempt to do a fast confirmation of a word match that covers a subset
    /// (but hopefully a big subset) of most cases. Ok(Some(..)) is returned
    /// when a match is found. Ok(None) is returned when there is definitively
    /// no match. Err(()) is returned when this routine could not detect
    /// whether there was a match or not.
    fn fast_find(
        &self,
        haystack: &[u8],
        at: usize,
    ) -> Result<Option<Match>, ()> {
        // This is a bit hairy. The whole point here is to avoid running a
        // slower regex engine to extract capture groups. Remember, our word
        // regex looks like this:
        //
        //     (^|\W)(<original regex>)(\W|$)
        //
        // What we want are the match offsets of <original regex>. So in the
        // easy/common case, the original regex will be sandwiched between
        // two codepoints that are in the \W class. So our approach here is to
        // look for a match of the overall word regexp, strip the \W ends and
        // then check whether the original regex matches what's left. If so,
        // then we are guaranteed a correct match.
        //
        // This only works though if we know that the match is sandwiched
        // between two \W codepoints. This only occurs when neither ^ nor $
        // match. This in turn only occurs when the match is at either the
        // beginning or end of the haystack. In either of those cases, we
        // declare defeat and defer to the slower implementation.
        //
        // The reason why we cannot handle the ^/$ cases here is because we
        // can't assume anything about the original pattern. (Try commenting
        // out the checks for ^/$ below and run the tests to see examples.)
        let input = Input::new(haystack).span(at..haystack.len());
        let mut cand = match self.regex.find(input) {
            None => return Ok(None),
            Some(m) => Match::new(m.start(), m.end()),
        };
        if cand.start() == 0 || cand.end() == haystack.len() {
            return Err(());
        }
        let (_, slen) = bstr::decode_utf8(&haystack[cand]);
        let (_, elen) = bstr::decode_last_utf8(&haystack[cand]);
        let new_start = cand.start() + slen;
        let new_end = cand.end() - elen;
        // This occurs the original regex can match the empty string. In this
        // case, just bail instead of trying to get it right here since it's
        // likely a pathological case.
        if new_start > new_end {
            return Err(());
        }
        cand = cand.with_start(new_start).with_end(new_end);
        if self.original.is_match(&haystack[cand]) {
            Ok(Some(cand))
        } else {
            Err(())
        }
    }
}

fn placeholder_regex() -> Regex {
    Regex::builder()
        .configure(Regex::config().utf8_empty(false))
        .build(r"a")
        .unwrap()
}

fn placeholder_chir() -> Arc<ConfiguredHIR> {
    Arc::new(ConfiguredHIR::from_parts(
        Config::default(),
        Hir::literal(b"a".as_ref()),
    ))
}

fn is_poisonous(lit: &hir::literal::Literal) -> bool {
    use regex_syntax::hir::literal::rank;

    lit.is_empty() || (lit.len() == 1 && rank(lit.as_bytes()[0]) >= 250)
}

#[derive(Clone, Debug)]
struct TSeq {
    seq: Seq,
    prefix: bool,
}

#[allow(dead_code)]
impl TSeq {
    fn empty() -> TSeq {
        TSeq { seq: Seq::empty(), prefix: true }
    }

    fn infinite() -> TSeq {
        TSeq { seq: Seq::infinite(), prefix: true }
    }

    fn singleton(lit: hir::literal::Literal) -> TSeq {
        TSeq { seq: Seq::singleton(lit), prefix: true }
    }

    fn literals(&self) -> Option<&[Literal]> {
        self.seq.literals()
    }

    fn push(&mut self, lit: hir::literal::Literal) {
        self.seq.push(lit);
    }

    fn make_inexact(&mut self) {
        self.seq.make_inexact();
    }

    fn make_infinite(&mut self) {
        self.seq.make_infinite();
    }

    fn cross_forward(&mut self, other: &mut TSeq) {
        self.seq.cross_forward(&mut other.seq);
    }

    fn union(&mut self, other: &mut TSeq) {
        self.seq.union(&mut other.seq);
    }

    fn dedup(&mut self) {
        self.seq.dedup();
    }

    fn keep_first_bytes(&mut self, len: usize) {
        self.seq.keep_first_bytes(len);
    }

    fn is_finite(&self) -> bool {
        self.seq.is_finite()
    }

    fn is_empty(&self) -> bool {
        self.seq.is_empty()
    }

    fn len(&self) -> Option<usize> {
        self.seq.len()
    }

    fn is_inexact(&self) -> bool {
        self.seq.is_inexact()
    }

    fn max_union_len(&self, other: &TSeq) -> Option<usize> {
        self.seq.max_union_len(&other.seq)
    }

    fn max_cross_len(&self, other: &TSeq) -> Option<usize> {
        assert!(other.prefix);
        self.seq.max_cross_len(&other.seq)
    }

    fn min_literal_len(&self) -> Option<usize> {
        self.seq.min_literal_len()
    }

    fn make_not_prefix(&mut self) {
        self.prefix = false;
    }
}

impl Matcher for WordMatcher {
    type Captures = RegexCaptures;
    type Error = NoError;

    fn find_at(
        &self,
        haystack: &[u8],
        at: usize,
    ) -> Result<Option<Match>, NoError> {
        if !self.word_mode {
            let input = Input::new(haystack).span(at..haystack.len());
            return Ok(
                self.regex.find(input).map(|m| Match::new(m.start(), m.end()))
            );
        }
        // To make this easy to get right, we extract captures here instead of
        // calling `find_at`. The actual match is at capture group `1` instead
        // of `0`. We *could* use `find_at` here and then trim the match after
        // the fact, but that's a bit harder to get right, and it's not clear
        // if it's worth it.
        //
        // OK, well, it turns out that it is worth it! But it is quite tricky.
        // See `fast_find` for details. Effectively, this lets us skip running
        // a slower regex engine to extract capture groups in the vast majority
        // of cases. However, the slower engine is I believe required for full
        // correctness.
        match self.fast_find(haystack, at) {
            Ok(Some(m)) => return Ok(Some(m)),
            Ok(None) => return Ok(None),
            Err(()) => {}
        }

        let input = Input::new(haystack).span(at..haystack.len());
        let mut caps = self.caps.get();
        self.regex.search_captures(&input, &mut caps);
        Ok(caps.get_group(1).map(|sp| Match::new(sp.start, sp.end)))
    }

    fn new_captures(&self) -> Result<RegexCaptures, NoError> {
        if !self.word_mode {
            return Ok(RegexCaptures::new(self.regex.create_captures()));
        }
        Ok(RegexCaptures::with_offset(self.regex.create_captures(), 1))
    }

    fn capture_count(&self) -> usize {
        if !self.word_mode {
            return self.regex.captures_len();
        }
        self.regex.captures_len().checked_sub(1).unwrap()
    }

    fn capture_index(&self, name: &str) -> Option<usize> {
        if !self.word_mode {
            return self.regex.group_info().to_index(PatternID::ZERO, name);
        }
        self.names.get(name).map(|i| *i)
    }

    fn captures_at(
        &self,
        haystack: &[u8],
        at: usize,
        caps: &mut RegexCaptures,
    ) -> Result<bool, NoError> {
        let input = Input::new(haystack).span(at..haystack.len());
        let caps = caps.captures_mut();
        self.regex.search_captures(&input, caps);
        Ok(caps.is_match())
    }

    fn try_find_iter<F, E>(
        &self,
        haystack: &[u8],
        mut matched: F,
    ) -> Result<Result<(), E>, NoError>
    where
        F: FnMut(Match) -> Result<bool, E>,
    {
        if self.word_mode {
            let mut at = 0;
            while at <= haystack.len() {
                let m = match self.find_at(haystack, at)? {
                    None => break,
                    Some(m) => m,
                };
                match matched(m) {
                    Ok(true) => {
                        at = if m.is_empty() { m.end() + 1 } else { m.end() };
                        continue;
                    }
                    Ok(false) => return Ok(Ok(())),
                    Err(err) => return Ok(Err(err)),
                }
            }
            return Ok(Ok(()));
        }
        for m in self.regex.find_iter(haystack) {
            match matched(Match::new(m.start(), m.end())) {
                Ok(true) => continue,
                Ok(false) => return Ok(Ok(())),
                Err(err) => return Ok(Err(err)),
            }
        }
        Ok(Ok(()))
    }

    fn shortest_match_at(
        &self,
        haystack: &[u8],
        at: usize,
    ) -> Result<Option<usize>, NoError> {
        if self.word_mode {
            return Ok(self.find_at(haystack, at)?.map(|m| m.end()));
        }
